import { DirectionProvider } from '@base-ui/react/direction-provider';
import { createContext, useContext, useEffect, useMemo, type ReactNode } from 'react';
import { createFormatters, localeDirection, type I18nFormatters } from './format';
import { catalogs } from './messages';
import { en, type Messages } from './messages/en';

export type Direction = 'ltr' | 'rtl';

/** What useI18n() returns: the translator, Intl formatters, the locale and the text direction. */
export interface I18n extends I18nFormatters {
  locale: string;
  dir: Direction;
}

export interface I18nProviderProps {
  /** BCP 47 locale ("es", "es-MX", "ar"). Picks the built-in catalog by language; unknown → English. */
  locale: string;
  /** Overrides or additions on top of the built-in catalog (e.g. a full catalog for another language). */
  messages?: Partial<Messages>;
  /** Text direction; defaults to the locale's (rtl for Arabic, Hebrew, Persian, Urdu…). */
  dir?: Direction;
  /**
   * Where `dir` and `lang` are applied: `wrapper` (default) renders a `display: contents` div;
   * `document` sets them on `<html>` (also covers portalled overlays); `none` leaves it to you.
   */
  applyTo?: 'wrapper' | 'document' | 'none';
  children?: ReactNode;
}

const I18nContext = createContext<I18n | null>(null);
const DEFAULT_I18N: I18n = { locale: 'en', dir: 'ltr', ...createFormatters('en', en) };

/** The built-in catalog for a locale's language, falling back to English. */
export function builtInMessages(locale: string): Messages {
  const lang = locale.split(/[-_]/)[0]?.toLowerCase() ?? '';
  return (catalogs as Record<string, Messages | undefined>)[lang] ?? en;
}

/**
 * Locale, messages and direction for every kit component below it. Also sets Base UI's
 * direction, so arrow-key navigation (Tabs, Menu, Slider, Toolbar…) follows RTL.
 */
export function I18nProvider({ locale, messages, dir, applyTo = 'wrapper', children }: I18nProviderProps) {
  const direction = dir ?? localeDirection(locale);
  const value = useMemo<I18n>(() => {
    const merged: Messages = { ...builtInMessages(locale), ...messages };
    return { locale, dir: direction, ...createFormatters(locale, merged) };
  }, [locale, messages, direction]);

  useEffect(() => {
    if (applyTo !== 'document') return;
    const html = document.documentElement;
    const prev = { dir: html.getAttribute('dir'), lang: html.getAttribute('lang') };
    html.setAttribute('dir', direction);
    html.setAttribute('lang', locale);
    return () => {
      if (prev.dir === null) html.removeAttribute('dir');
      else html.setAttribute('dir', prev.dir);
      if (prev.lang === null) html.removeAttribute('lang');
      else html.setAttribute('lang', prev.lang);
    };
  }, [applyTo, direction, locale]);

  const content = <DirectionProvider direction={direction}>{children}</DirectionProvider>;
  return (
    <I18nContext.Provider value={value}>
      {applyTo === 'wrapper' ? (
        <div dir={direction} lang={locale} className="contents">
          {content}
        </div>
      ) : (
        content
      )}
    </I18nContext.Provider>
  );
}

/** Translator, Intl formatters, locale and direction. Outside an I18nProvider: English, LTR. */
export function useI18n(): I18n {
  return useContext(I18nContext) ?? DEFAULT_I18N;
}

/** The provider's value, or null outside one (lets components keep runtime-locale defaults). */
export function useOptionalI18n(): I18n | null {
  return useContext(I18nContext);
}

/**
 * `dir` for portalled overlays: rendered outside the provider's wrapper, they carry the
 * direction themselves. Undefined outside a provider, so the document's direction applies.
 */
export function usePortalDir(): Direction | undefined {
  return useContext(I18nContext)?.dir;
}

import type { MessageKey, Messages } from './messages/en';

/** Values interpolated into a message: `{name}` placeholders and plural selectors. */
export type MessageVars = Record<string, string | number>;

/** Scripts written right to left (language subtag). */
const RTL_LANGUAGES = new Set(['ar', 'arc', 'ckb', 'dv', 'fa', 'he', 'iw', 'ks', 'ku', 'ps', 'sd', 'ug', 'ur', 'yi']);

/** `rtl` for Arabic, Hebrew, Persian, Urdu… (by language subtag or Intl text info), else `ltr`. */
export function localeDirection(locale: string): 'ltr' | 'rtl' {
  try {
    const loc = new Intl.Locale(locale) as Intl.Locale & {
      getTextInfo?: () => { direction?: string };
      textInfo?: { direction?: string };
    };
    const info = loc.getTextInfo?.() ?? loc.textInfo;
    if (info?.direction === 'rtl' || info?.direction === 'ltr') return info.direction;
    return RTL_LANGUAGES.has(loc.language) ? 'rtl' : 'ltr';
  } catch {
    return RTL_LANGUAGES.has(locale.split(/[-_]/)[0]?.toLowerCase() ?? '') ? 'rtl' : 'ltr';
  }
}

/** Index of the brace closing the one at `open` (nested braces allowed). */
function matchBrace(text: string, open: number): number {
  let depth = 0;
  for (let i = open; i < text.length; i++) {
    if (text[i] === '{') depth++;
    else if (text[i] === '}' && --depth === 0) return i;
  }
  return -1;
}

/** `one {# item} other {# items}` → `{ one: '# item', other: '# items' }`. */
function parseBranches(body: string): Record<string, string> {
  const branches: Record<string, string> = {};
  let i = 0;
  while (i < body.length) {
    const open = body.indexOf('{', i);
    if (open < 0) break;
    const name = body.slice(i, open).trim();
    const close = matchBrace(body, open);
    if (close < 0) break;
    branches[name] = body.slice(open + 1, close);
    i = close + 1;
  }
  return branches;
}

/** Fills `{name}` placeholders and `{count, plural, one {…} other {…}}` selectors. */
export function interpolate(template: string, vars: MessageVars | undefined, locale: string): string {
  if (!vars || !template.includes('{')) return template;
  let out = '';
  let i = 0;
  while (i < template.length) {
    const open = template.indexOf('{', i);
    if (open < 0) {
      out += template.slice(i);
      break;
    }
    out += template.slice(i, open);
    const close = matchBrace(template, open);
    if (close < 0) {
      out += template.slice(open);
      break;
    }
    const inner = template.slice(open + 1, close);
    const plural = /^\s*(\w+)\s*,\s*plural\s*,(.*)$/s.exec(inner);
    if (plural) {
      const name = plural[1] ?? '';
      const n = Number(vars[name] ?? 0);
      const branches = parseBranches(plural[2] ?? '');
      const rule = new Intl.PluralRules(locale).select(n);
      const branch = branches[`=${n}`] ?? branches[rule] ?? branches.other ?? '';
      out += interpolate(branch.replaceAll('#', new Intl.NumberFormat(locale).format(n)), vars, locale);
    } else {
      const value = vars[inner.trim()];
      out += value === undefined ? `{${inner}}` : String(value);
    }
    i = close + 1;
  }
  return out;
}

export type DateValue = Date | number | string;
const toDate = (value: DateValue) => (value instanceof Date ? value : new Date(value));

const RELATIVE_UNITS: [Intl.RelativeTimeFormatUnit, number][] = [
  ['year', 365 * 24 * 3600],
  ['month', 30 * 24 * 3600],
  ['week', 7 * 24 * 3600],
  ['day', 24 * 3600],
  ['hour', 3600],
  ['minute', 60],
  ['second', 1],
];

/** The translator and Intl formatters for one locale. */
export interface I18nFormatters {
  /** Translates a built-in key, filling placeholders. */
  t: (key: MessageKey, vars?: MessageVars) => string;
  formatNumber: (value: number, options?: Intl.NumberFormatOptions) => string;
  formatCurrency: (value: number, currency: string, options?: Intl.NumberFormatOptions) => string;
  formatDate: (value: DateValue, options?: Intl.DateTimeFormatOptions) => string;
  /**
   * Relative time. With a unit, formats `value` in it ("in 3 days"); with a date, picks the
   * largest fitting unit against `now` ("5 minutes ago").
   */
  formatRelativeTime: {
    (value: number, unit: Intl.RelativeTimeFormatUnit, options?: Intl.RelativeTimeFormatOptions): string;
    (value: Date, now?: Date | number, options?: Intl.RelativeTimeFormatOptions): string;
  };
  formatList: (items: readonly string[], options?: Intl.ListFormatOptions) => string;
}

export function createFormatters(locale: string, messages: Messages): I18nFormatters {
  function formatRelativeTime(value: number, unit: Intl.RelativeTimeFormatUnit, options?: Intl.RelativeTimeFormatOptions): string;
  function formatRelativeTime(value: Date, now?: Date | number, options?: Intl.RelativeTimeFormatOptions): string;
  function formatRelativeTime(
    value: number | Date,
    unitOrNow?: Intl.RelativeTimeFormatUnit | Date | number,
    options: Intl.RelativeTimeFormatOptions = { numeric: 'auto' },
  ): string {
    const rtf = new Intl.RelativeTimeFormat(locale, options);
    if (typeof value === 'number' && typeof unitOrNow === 'string') return rtf.format(value, unitOrNow);
    const now = unitOrNow instanceof Date ? unitOrNow.getTime() : typeof unitOrNow === 'number' ? unitOrNow : Date.now();
    const seconds = Math.round((toDate(value).getTime() - now) / 1000);
    const [unit, size] = RELATIVE_UNITS.find(([, s]) => Math.abs(seconds) >= s) ?? ['second', 1];
    return rtf.format(Math.round(seconds / size), unit);
  }
  return {
    t: (key, vars) => interpolate(messages[key] ?? key, vars, locale),
    formatNumber: (value, options) => new Intl.NumberFormat(locale, options).format(value),
    formatCurrency: (value, currency, options) => new Intl.NumberFormat(locale, { style: 'currency', currency, ...options }).format(value),
    formatDate: (value, options = { dateStyle: 'medium' }) => new Intl.DateTimeFormat(locale, options).format(toDate(value)),
    formatRelativeTime,
    formatList: (items, options = { style: 'long', type: 'conjunction' }) => new Intl.ListFormat(locale, options).format(items),
  };
}

import { en, type Messages } from './en';
import { es } from './es';

/** Built-in catalogs, by language subtag. */
export const catalogs = { en, es } satisfies Record<string, Messages>;
export type CatalogLocale = keyof typeof catalogs;

import { Menu as MenuIcon, PanelLeftClose, PanelLeftOpen } from 'lucide-react';
import { createContext, useContext, useId, useState, type ReactNode } from 'react';
import { cn } from '../../utils/cn';
import { IconButton } from '../../ui/button';
import { Drawer, DrawerBody, DrawerContent, DrawerHeader, DrawerTitle, DrawerTrigger } from '../../ui/drawer';
import { SkipLink } from '../../ui/visually-hidden';
import { sidebarLayoutVariants } from './sidebar-layout.variants';
import { useI18n } from '../../i18n/I18nProvider';
import { usePersistedCollapse } from './use-persisted-collapse';

/** State handed to sidebar slots, so they can adapt (icon rail) or close the mobile drawer. */
export interface SidebarSlotState {
  /** The desktop sidebar is collapsed (icon rail or off-canvas). Always false inside the drawer. */
  collapsed: boolean;
  /** The slot is rendered inside the small-screen drawer. */
  inDrawer: boolean;
  /** Closes the small-screen drawer (no-op on the desktop sidebar). Call it after navigating. */
  closeDrawer: () => void;
}

/** A sidebar slot: plain content, or a function of the sidebar state. */
export type SidebarSlot = ReactNode | ((state: SidebarSlotState) => ReactNode);

export interface SidebarLayoutContextValue {
  collapsed: boolean;
  setCollapsed: (collapsed: boolean) => void;
  toggleCollapsed: () => void;
  drawerOpen: boolean;
  setDrawerOpen: (open: boolean) => void;
}

const SidebarLayoutContext = createContext<SidebarLayoutContextValue | null>(null);

/** Sidebar state for anything rendered inside a SidebarLayout (e.g. a custom collapse button). */
export function useSidebarLayout(): SidebarLayoutContextValue {
  const ctx = useContext(SidebarLayoutContext);
  if (!ctx) throw new Error('useSidebarLayout must be used inside <SidebarLayout>.');
  return ctx;
}

export interface SidebarLayoutProps {
  className?: string;
  /** Sidebar body, usually a NavList (pass a function to get `collapsed` for the icon rail). */
  sidebar: SidebarSlot;
  /** Top of the sidebar: logo or workspace switcher. */
  sidebarHeader?: SidebarSlot;
  /** Bottom of the sidebar: usage, help, user. */
  sidebarFooter?: SidebarSlot;
  /** Topbar content after the menu / collapse buttons: breadcrumb, ⌘K, notifications, theme, user menu. */
  topbar?: ReactNode;
  /** Main content. */
  children?: ReactNode;
  /** What "collapsed" means on large screens: a 64px icon rail or a fully hidden sidebar. */
  collapseMode?: 'rail' | 'offcanvas';
  /** Shows the collapse toggle in the topbar (large screens). */
  collapsible?: boolean;
  collapsed?: boolean;
  defaultCollapsed?: boolean;
  onCollapsedChange?: (collapsed: boolean) => void;
  /** Persists the uncontrolled collapsed state in localStorage under this key. */
  storageKey?: string;
  /** Small-screen drawer state. */
  drawerOpen?: boolean;
  onDrawerOpenChange?: (open: boolean) => void;
  /** Accessible name of the sidebar landmark and of the small-screen drawer. */
  sidebarLabel?: string;
  /** `id` of <main>, target of the skip link. */
  mainId?: string;
  skipLinkLabel?: string;
  menuLabel?: string;
  collapseLabel?: string;
  expandLabel?: string;
  /** Fill the viewport (h-dvh) instead of the container. */
  fullScreen?: boolean;
}

function renderSlot(slot: SidebarSlot, state: SidebarSlotState) {
  return typeof slot === 'function' ? slot(state) : slot;
}

/**
 * Application shell: collapsible sidebar (expanded, icon rail or off-canvas) · topbar · main.
 * Below `lg` the sidebar moves into a left Drawer opened from the topbar menu button.
 * Fills its container (`fullScreen` for h-dvh) and never uses fixed positioning.
 */
export function SidebarLayout({
  className,
  sidebar,
  sidebarHeader,
  sidebarFooter,
  topbar,
  children,
  collapseMode = 'rail',
  collapsible = true,
  collapsed: collapsedProp,
  defaultCollapsed = false,
  onCollapsedChange,
  storageKey,
  drawerOpen: drawerOpenProp,
  onDrawerOpenChange,
  sidebarLabel: sidebarLabelProp,
  mainId = 'main',
  skipLinkLabel: skipLinkLabelProp,
  menuLabel: menuLabelProp,
  collapseLabel: collapseLabelProp,
  expandLabel: expandLabelProp,
  fullScreen = false,
}: SidebarLayoutProps) {
  const { t } = useI18n();
  const sidebarLabel = sidebarLabelProp ?? t('nav.sidebar');
  const skipLinkLabel = skipLinkLabelProp ?? t('skip.main');
  const menuLabel = menuLabelProp ?? t('nav.openNavigation');
  const collapseLabel = collapseLabelProp ?? t('nav.collapseSidebar');
  const expandLabel = expandLabelProp ?? t('nav.expandSidebar');
  const sidebarId = useId();
  const [collapsed, setCollapsed] = usePersistedCollapse(collapsedProp, defaultCollapsed, storageKey, onCollapsedChange);
  const [drawerState, setDrawerState] = useState(false);
  const drawerOpen = drawerOpenProp ?? drawerState;
  const setDrawerOpen = (open: boolean) => {
    setDrawerState(open);
    onDrawerOpenChange?.(open);
  };
  const isCollapsed = collapsible && collapsed;
  const state = isCollapsed ? collapseMode : 'expanded';
  const s = sidebarLayoutVariants({ fullScreen, state });
  const desktop: SidebarSlotState = { collapsed: isCollapsed, inDrawer: false, closeDrawer: () => {} };
  const mobile: SidebarSlotState = { collapsed: false, inDrawer: true, closeDrawer: () => setDrawerOpen(false) };
  const ctx: SidebarLayoutContextValue = {
    collapsed: isCollapsed,
    setCollapsed,
    toggleCollapsed: () => setCollapsed(!collapsed),
    drawerOpen,
    setDrawerOpen,
  };
  const hidden = state === 'offcanvas';

  return (
    <SidebarLayoutContext.Provider value={ctx}>
      <div className={cn(s.root(), className)} data-sidebar-state={state}>
        <SkipLink targetId={mainId} className={s.skip()}>
          {skipLinkLabel}
        </SkipLink>
        <aside id={sidebarId} aria-label={sidebarLabel} data-state={state} inert={hidden || undefined} className={s.sidebar()}>
          {sidebarHeader && <div className={s.sidebarHeader()}>{renderSlot(sidebarHeader, desktop)}</div>}
          <div className={s.sidebarBody()}>{renderSlot(sidebar, desktop)}</div>
          {sidebarFooter && <div className={s.sidebarFooter()}>{renderSlot(sidebarFooter, desktop)}</div>}
        </aside>
        <div className={s.column()}>
          <header className={s.topbar()}>
            <Drawer side="left" open={drawerOpen} onOpenChange={(open) => setDrawerOpen(open)}>
              <DrawerTrigger render={<IconButton icon={MenuIcon} label={menuLabel} className={s.menuButton()} />} />
              <DrawerContent size="sm" className={s.drawer()} closeLabel={t('nav.closeNavigation')}>
                <DrawerHeader className={s.drawerHeader()}>
                  <DrawerTitle className={sidebarHeader ? 'sr-only' : undefined}>{sidebarLabel}</DrawerTitle>
                  {sidebarHeader && renderSlot(sidebarHeader, mobile)}
                </DrawerHeader>
                <DrawerBody className={s.drawerBody()}>
                  {renderSlot(sidebar, mobile)}
                  {sidebarFooter && renderSlot(sidebarFooter, mobile)}
                </DrawerBody>
              </DrawerContent>
            </Drawer>
            {collapsible && (
              <IconButton
                icon={isCollapsed ? PanelLeftOpen : PanelLeftClose}
                label={isCollapsed ? expandLabel : collapseLabel}
                aria-expanded={!isCollapsed}
                aria-controls={sidebarId}
                className={s.collapseButton()}
                onClick={() => setCollapsed(!collapsed)}
              />
            )}
            <div className={s.topbarContent()}>{topbar}</div>
          </header>
          <main id={mainId} tabIndex={-1} className={s.main()}>
            {children}
          </main>
        </div>
      </div>
    </SidebarLayoutContext.Provider>
  );
}

export {
  SidebarLayout,
  useSidebarLayout,
  type SidebarLayoutProps,
  type SidebarLayoutContextValue,
  type SidebarSlot,
  type SidebarSlotState,
} from './SidebarLayout';
export { sidebarLayoutVariants, type SidebarLayoutVariantProps } from './sidebar-layout.variants';
export { doc as sidebarLayoutDoc } from './SidebarLayout.doc';

import { tv, type VariantProps } from '../../utils/tv';

export const sidebarLayoutVariants = tv({
  slots: {
    root: 'relative flex w-full min-w-0 overflow-hidden bg-background font-sans text-foreground',
    skip: 'focus:absolute',
    sidebar: [
      'hidden shrink-0 flex-col overflow-hidden border-e border-border/60 bg-chrome lg:flex',
      'transition-[width] duration-200 motion-reduce:transition-none',
    ],
    sidebarHeader: 'flex shrink-0 items-center px-3 pt-4 pb-3',
    sidebarBody: 'min-h-0 flex-1 overflow-x-hidden overflow-y-auto px-3 pt-1 pb-3',
    sidebarFooter: 'shrink-0 p-2.5',
    column: 'flex min-h-0 min-w-0 flex-1 flex-col',
    topbar: 'flex h-14 shrink-0 items-center gap-2 border-b border-border/60 bg-chrome px-3 lg:gap-3 lg:px-5',
    topbarContent: 'flex min-w-0 flex-1 items-center gap-2 lg:gap-3',
    menuButton: 'lg:hidden',
    collapseButton: 'hidden lg:inline-flex',
    main: 'min-h-0 flex-1 overflow-y-auto focus:outline-none',
    drawer: 'bg-chrome',
    drawerHeader: 'px-3',
    drawerBody: 'flex flex-col gap-3 px-3 py-3',
  },
  variants: {
    fullScreen: { true: { root: 'h-dvh' }, false: { root: 'h-full min-h-0' } },
    state: {
      expanded: { sidebar: 'w-[248px]' },
      rail: { sidebar: 'w-16', sidebarHeader: 'justify-center px-2', sidebarBody: 'px-2', sidebarFooter: 'px-2' },
      offcanvas: { sidebar: 'w-0 border-e-0' },
    },
  },
  defaultVariants: { fullScreen: false, state: 'expanded' },
});

export type SidebarLayoutVariantProps = VariantProps<typeof sidebarLayoutVariants>;

import { useState } from 'react';

function read(storageKey: string | undefined): boolean | undefined {
  if (!storageKey || typeof window === 'undefined') return undefined;
  try {
    const value = window.localStorage.getItem(storageKey);
    return value === null ? undefined : value === 'true';
  } catch {
    return undefined;
  }
}

function write(storageKey: string | undefined, value: boolean) {
  if (!storageKey || typeof window === 'undefined') return;
  try {
    window.localStorage.setItem(storageKey, String(value));
  } catch {}
}

/** Controlled / uncontrolled boolean whose uncontrolled value survives reloads under `storageKey`. */
export function usePersistedCollapse(
  controlled: boolean | undefined,
  defaultValue: boolean,
  storageKey: string | undefined,
  onChange: ((value: boolean) => void) | undefined,
) {
  const [state, setState] = useState(() => read(storageKey) ?? defaultValue);
  const value = controlled ?? state;
  const set = (next: boolean) => {
    setState(next);
    write(storageKey, next);
    onChange?.(next);
  };
  return [value, set] as const;
}
